from sympy import factorint

def a(n):
    return 6**n + 2**n + 3**n - 1

N_values = range(11, 16)
results = {}

for n in N_values:
    val = a(n)
    factorization = factorint(val)
    results[n] = (val, factorization)

print("--- Calculated Terms and Factorizations ---")
for n, (val, factors) in results.items():
    print(f"a_{n} = {val}")
    print(f"Factorization of a_{n}: {factors}")

# Collect all unique prime factors
unique_primes = set()
for n, (val, factors) in results.items():
    for p in factors.keys():
        unique_primes.add(p)

print("\n--- Unique Prime Factors ---")
print(sorted(list(unique_primes)))

def factorize(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def calculate_sequence_and_factors(N_max):
    a = {}
    a[1] = 10
    factors = set([2, 5])

    # Candidate B's claimed primes P (for comparison)
    P_B = {2, 3, 5, 7, 11, 19, 23, 29, 41, 199, 659, 1129, 1597, 2239}

    for n in range(1, N_max):
        if n == 1:
            a_next = 6 * a[n] - 2**(n+2) - 3**(n+1) + 5
        else:
             a_next = 6 * a[n] - 2**(n+2) - 3**(n+1) + 5

        a[n+1] = a_next

        current_factors = factorize(a_next)
        factors.update(current_factors)

        if n+1 <= 8: # Only check up to 8 for practical testing against B's range
             print(f"a_{n+1} = {a[n+1]}, Factors: {current_factors}")
             if current_factors - P_B:
                 print(f"--- Discrepancy found at n={n+1}. Missing prime factor(s): {current_factors - P_B}")

    return factors

# Run calculation up to n=8
all_factors = calculate_sequence_and_factors(8)
print(f"\nAll prime factors found up to a_8: {sorted(list(all_factors))}")
